INSERT INTO `courses` (`id`, `name`, `description`, `creation_date`, `author`) VALUES
(1, 'Full Stack Web Developer', '<h4>Program Overview</h4>\r\n<p>The Dinzin Full Stack Web Developer Training Program is an intensive 3-month course designed to equip aspiring developers with the skills and knowledge needed to build dynamic, responsive, and scalable web applications. This program combines theoretical learning with hands-on projects to ensure participants gain practical experience in both front-end and back-end development.</p>\r\n<p>&nbsp;</p>', '2024-07-23 18:48:42', '');
