INSERT INTO `job_openings` (`id`, `title`, `description`, `location`, `is_active`, `date_posted`) VALUES
(1, 'Web Development Intern', '<li>Design and implement high-quality software solutions.</li>\r\n<li>Collaborate with cross-functional teams to develop innovative applications.</li>\r\n<li>Stay updated on industry trends and incorporate best practices into coding processes.</li>\r\n<li>Preferred skills: HTML, CSS, JS and PHP</li>', 'Remote, India', 0, '2024-03-09 00:35:45'),
(3, 'Content Writer Intern ', 'Are you passionate about both content writing and technology? Dinzin, a leading tech and software company, is excited to offer a unique internship opportunity for content writers to blend their love for writing with the dynamic world of technology.<br><br>\r\n<b>Company Overview:</b><br>\r\nDinzin is at the forefront of innovation, specializing in cutting-edge web development and software solutions. We\'re dedicated to pushing boundaries and delivering top-notch services to our clients while fostering growth and creativity within our team.<br><br>\r\nPosition: Content Writer Intern<br>\r\nSalary: Unpaid<br><br>\r\n<b>Benefits:</b><br>\r\n<li>Flexible Hours</li>\r\n<li>Work from Home</li>\r\n<li>Certificates:</li>\r\n<li>Duration: 3 Months</li><br><br>\r\n<b>Roles and Responsibilities:</b><br><br>\r\nAs a Content Writer Intern at Dinzin, you\'ll play a crucial role in:<br><br>\r\n<li>Create compelling and original content for various platforms, including blog posts, social media, and website copy.</li>\r\n<li>Conduct research to gather information and insights for content development.</li>\r\n<li>Collaborate with the marketing team to brainstorm ideas and develop content strategies.</li>\r\n<li>Proofread and edit content to ensure accuracy, clarity, and consistency.</li>\r\n<li>Stay up-to-date with industry trends and best practices in content writing and digital marketing.</li>\r\n<li>Assist in managing and maintaining content calendars and schedules.</li>\r\n<li>Participate in team meetings and contribute creative ideas to enhance content quality and engagement.</li><br><br>\r\n<b>Qualifications:</b><br><br>\r\n<li>Strong writing skills with a keen eye for detail and grammar.</li>\r\n<li>Excellent research abilities to gather relevant information.</li>\r\n<li>Creativity and a passion for storytelling.</li>\r\n<li>Ability to work independently and meet deadlines.</li>\r\n<li>Basic understanding of SEO principles is a plus.</li>\r\n\r\n\r\n\r\n\r\n\r\n\r\n', 'Remote, India', 0, '2024-03-16 13:14:09'),
(4, 'Research Analyst Intern', 'Are you a passionate individual eager to dive into the world of research and analysis? Look no further! Dinzin is offering an exciting opportunity for a Research Analyst Intern to join our dynamic team.<br><br>\r\n\r\n<b>Company Overview:</b><br>\r\nDinzin is at the forefront of innovation, specializing in cutting-edge web development and software solutions. We\'re dedicated to pushing boundaries and delivering top-notch services to our clients while fostering growth and creativity within our team.<br><br>\r\n\r\nPosition: Research Analyst Intern<br>\r\nSalary: Unpaid<br><br>\r\n<b>Benefits:</b><br>\r\n<li>Flexible Hours</li>\r\n<li>Work from Home</li>\r\n<li>Certificates</li>\r\n<li>Duration: 3 Months</li><br><br>\r\n\r\n<b>Roles and Responsibilities:</b><br><br>\r\n\r\n<li> Conducting research on industry trends, market analysis, and competitor insights.</li>\r\n<li>Collecting and analyzing data to identify patterns, trends, and opportunities.</li>\r\n<li>Assisting in the preparation of reports, presentations, and strategic recommendations for clients.</li>\r\n<li>Collaborating with team members to brainstorm ideas and contribute to ongoing projects.</li><br><br>\r\n\r\n<b>Requirements:</b><br><br>\r\n<li>Currently pursuing a degree in Business, Economics, Marketing, or related field.</li>\r\n<li>Strong analytical skills with the ability to interpret data and draw meaningful insights.</li>\r\n<li>Excellent communication skills, both written and verbal.</li>\r\n<li>Proficiency in Microsoft Office suite (Excel, PowerPoint, Word).</li>\r\n<li>Self-motivated and able to work independently with minimal supervision.</li><br><br>\r\n\r\n', 'Remote, India', 0, '2024-03-19 18:13:16'),
(6, 'Digital Marketing Intern', 'Are you a social media whiz with a passion for creative content? Do you love diving deep into data and analytics? If so, then Dinzin wants you! We\'re offering an exciting opportunity for a Digital Marketing Intern to join our growing team.<br><br>\r\n<b>Company Overview:</b><br>\r\nDinzin is at the forefront of innovation, specializing in cutting-edge web development and software solutions. We\'re dedicated to pushing boundaries and delivering top-notch services to our clients while fostering growth and creativity within our team.<br><br>\r\nPosition: Digital Marketing Intern<br>\r\nSalary: Unpaid<br><br>\r\n<b>Benefits:</b><br>\r\n<li>Flexible Hours</li>\r\n<li>Work from Home</li>\r\n<li>Certificates:</li>\r\n<li>Duration: 3 Months</li><br><br>\r\n<b>Roles and Responsibilities:</b><br><br>\r\n<li>Assist in developing and executing engaging social media campaigns across various platforms.</li>\r\n<li>Create compelling content (written, visual, and video) to promote Dinzin\'s brand and services.</li>\r\n<li>Analyze social media performance metrics and identify areas for improvement.</li>\r\n<li>Participate in content brainstorming sessions and contribute fresh ideas.</li>\r\n<li>Stay up-to-date on the latest digital marketing trends and tools.</li><br><br>\r\n\r\n<b>Requirements:</b><br><br>\r\n<li>Currently pursuing a degree in Marketing, Communications, or a related field.</li>\r\n<li>Strong understanding of social media platforms (Facebook, Instagram, YouTube, etc.) and digital marketing best practices.</li>\r\n<li>Excellent written and verbal communication skills.</li>\r\n<li>Proficient in creative content creation tools (e.g., Canva)</li>\r\n<li>Analytical mindset with the ability to track and interpret data.</li>\r\n<li>Highly organized and detail-oriented with a passion for learning.</li>', 'Remote, India', 0, '2024-05-02 13:22:42'),
(9, 'Web Developer', 'ðŸš¨ Please Read Before Applying: This is NOT a salaried job. This is a partnership opportunity. You will earn a share of the profits generated by the product we\'re building. Only apply if you\'re open to working on a revenue-sharing model. ðŸš¨\r\n\r\n\r\n\r\nCompany Description\r\n\r\nWelcome to DinZin Technology Solutions Pvt Ltd â€” where innovation meets excellence in software solutions! We are on a mission to transform the digital landscape with tailored software products that deliver real impact. Our team thrives on collaboration, creativity, and a shared vision for building something meaningful.\r\n\r\n\r\n\r\nRole Description\r\n\r\nWe\'re looking for a passionate Web Developer to join our journey as a partner, not just an employee. This is a part-time, remote role where youâ€™ll contribute to building a product from the ground up. Currently, we are in the early development phase and there is no revenue â€” but once the product is launched, youâ€™ll earn a share of the profits.\r\n\r\n\r\n\r\nYour responsibilities will include:\r\n\r\nDeveloping and maintaining web applications (front-end and back-end)\r\nWriting clean, maintainable PHP, MySQL, HTML, CSS, and jQuery code\r\nTroubleshooting and improving existing systems\r\nCollaborating with the core team to bring the product vision to life\r\n\r\n\r\nQualifications\r\n\r\nStrong experience in PHP and MySQL for back-end development\r\nFront-end skills with HTML, CSS, and jQuery\r\nUnderstanding of responsive design and basic UI/UX principles\r\nAbility to work independently in a startup-style environment\r\nEntrepreneurial mindset with a passion for building and growing products\r\nBachelor\'s degree in Computer Science (or equivalent knowledge/experience)', 'Remote', 0, '2025-05-05 20:06:48');
INSERT INTO `legal` (`id`, `title`, `content`, `created`, `updated`, `publish`) VALUES
(2, 'Terms and Conditions', '<p class=\"MsoNormal\" style=\"line-height: 1;\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">Last Updated: 05-08-2024</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\"><strong>Welcome to Dinzin Technology Solutions Pvt Ltd!</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">These terms and conditions outline the rules and regulations for the use of Dinzin Technology Solutions Pvt Ltd\'s Website and Services, located at <a href=\"https://www.dinzin.in\"><strong>www.dinzin.in</strong></a>.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">By accessing this website and/or using our services, we assume you accept these terms and conditions. Do not continue to use Dinzin Technology Solutions Pvt Ltd, if you do not agree to all the terms and conditions stated on this page.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;1. <strong>Definitions</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- Client: Refers to any individual or business that uses the services provided by Dinzin Technology Solutions Pvt Ltd.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- Services: Refers to all products and services provided by Dinzin Technology Solutions Pvt Ltd, including but not limited to software building, web development, and website building.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- Deliverables: Refers to any software, website, or other digital products created by Dinzin Technology Solutions Pvt Ltd for the Client.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;2. <strong>Services</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">Dinzin Technology Solutions Pvt Ltd offers various services, including software development, web development, and website building. Specific terms of each service will be agreed upon in a separate Service Agreement.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">3. <strong>Payment Terms</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- Payment terms will be specified in the Service Agreement.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- Late payments may incur additional fees and interest as specified in the Service Agreement.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- Dinzin Technology Solutions Pvt Ltd reserves the right to suspend services if payments are not made in accordance with the agreed terms.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">4. <strong>Client Obligations</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- Provide accurate and complete information as required for the provision of services.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- Ensure timely communication and cooperation to facilitate project completion.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- Review and approve deliverables within the specified time frame.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">5. <strong>Confidentiality</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">Both parties agree to keep all confidential information disclosed during the course of the project confidential and not to use or disclose such information except as necessary to perform the services.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">6. <strong>Intellectual Property</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- Dinzin Technology Solutions Pvt Ltd retains ownership of all intellectual property rights to any materials created before or during the provision of services, except as otherwise agreed in writing.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- Upon full payment, the Client is granted a non-exclusive, non-transferable license to use the deliverables for their intended purpose.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">7. <strong>Warranties and Limitation of Liability</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- Dinzin Technology Solutions Pvt Ltd warrants that the services will be provided in a professional and workmanlike manner.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- To the maximum extent permitted by law, Dinzin Technology Solutions Pvt Ltd shall not be liable for any indirect, incidental, or consequential damages arising out of or in connection with the services.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">8. <strong>Termination</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- Either party may terminate the Service Agreement with 07 days\' written notice.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- Upon termination, the Client will pay for all services rendered up to the date of termination.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">9. <strong>Project Completion Timeline</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- The timeline for project completion will be agreed upon in the Service Agreement.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- If there are any delays in the project due to unforeseen circumstances or any other reasons, Dinzin Technology Solutions Pvt Ltd will inform the Client in advance and provide a revised timeline.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">10. <strong>Governing Law</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">These terms and conditions are governed by and construed in accordance with the laws of Bengaluru, and you irrevocably submit to the exclusive jurisdiction of the courts in that State or location.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">11. <strong>Changes to Terms</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">Dinzin Technology Solutions Pvt Ltd reserves the right to revise these terms and conditions at any time. By continuing to use the services after any changes are made, you agree to be bound by the revised terms.</span></p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"line-height: 1;\">&nbsp;</p>', '2024-08-04 17:30:55', '2024-08-05 07:56:04', 1),
(3, 'Refund Policy', '<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">At Dinzin Technology Solutions Pvt Ltd, we strive to provide the best possible service to our clients. We understand that circumstances may change, and you may need to cancel your project. Please review our Refunds and Cancellations Policy carefully.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">&nbsp;1. <strong>Cancellation Policy</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">1.1 Cancellation Within 24 Hours:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">- Clients may cancel their project within 24 hours of signing the agreement for a full refund.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">- To cancel within this period, please contact us immediately at Contact@dinzin.in.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">1.2 Cancellation After 24 Hours:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">- If a project is cancelled after 24 hours but before work has started, a cancellation fee of 2% of the total project cost will be charged.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">- If a project is cancelled after work has commenced, refunds will be processed based on the progress of the project as detailed below.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">2. <strong>Refund Policy</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">2.1 Refund Based on Project Progress:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">- Initial Phase: If the project is cancelled after the initial planning phase but before development has started, 5% of the total project cost will be refunded.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">- Development Phase: If the project is cancelled during the development phase, refunds will be processed proportionally based on the amount of work completed. The specific amount will be determined by Dinzin Technology Solutions Pvt Ltd and will reflect the time and resources invested up to the point of cancellation.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">- Final Phase: If the project is near completion (90% or more), no refund will be provided.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">2.2 Processing Refunds:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">- All refunds will be credited within 7 business days from the date of the cancellation request approval.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">- Refunds will be issued using the same method of payment that was used for the initial transaction unless otherwise agreed upon.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">3. <strong>How to Request a cancellation or Refund</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">- To request a cancellation or refund, please contact our support team at Contact@dinzin.in.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">- Provide your project details, including the agreement number and reason for the cancellation or refund request.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">&nbsp;4. <strong>Non-Refundable Services</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">Certain services are non-refundable, including but not limited to:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">- Domain registration fees</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">- Third-party software licenses</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">- Any other services or products explicitly stated as non-refundable in the agreement</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">&nbsp;5. <strong>Dispute Resolution</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">If you have any disputes regarding our Refunds and Cancellations Policy, please contact us at payments@dinzin.in. We aim to resolve any issues amicably and fairly.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">&nbsp;6. <strong>Changes to This Policy</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">Dinzin Technology Solutions Pvt Ltd reserves the right to modify or update this Refunds and Cancellations Policy at any time. Changes will be effective immediately upon posting on our website. We encourage you to review this policy periodically.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 14pt;\">&nbsp;</span></p>', '2024-08-04 17:32:44', '2024-11-30 11:11:43', 1),
(4, 'Privacy Policy', '<p>&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">At Dinzin Technology Solutions Pvt Ltd, your privacy is our topmost priority. We are committed to protecting your personal information and ensuring that your experience with us is safe and secure. This Privacy Policy outlines how we collect, use, disclose, and protect your information.</span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">1. <strong>Information We Collect</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">1.1 Personal Information:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- When you engage with our services, we may collect personal information such as your name, email address, phone number, company name, and payment information.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">1.2 Project Information:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- We may collect details about your project requirements, specifications, and other related information necessary for providing our services.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">1.3 Usage Information:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- We may collect information about how you use our website and services, including your IP address, browser type, and browsing behaviour.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">2. <strong>How We Use Your Information</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">2.1 Providing Services:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- To deliver and manage the services you request.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- To communicate with you about your project and provide support.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">2.2 Improving Our Services:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- To improve and personalize our services based on your feedback and interactions.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">2.3 Billing and Payments:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- To process payments and manage billing information.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">3. <strong>Data Sharing and Disclosure</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">3.1 No Sharing for Marketing:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- We do not share, sell, or rent your personal information to third parties for any marketing purposes.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">3.2 Service Providers:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- We may share your information with trusted third-party service providers who assist us in delivering our services. These providers are bound by confidentiality agreements and are not permitted to use your information for any other purposes.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">3.3 Legal Requirements:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- We may disclose your information if required by law, to protect our rights, or to comply with a judicial proceeding, court order, or legal process.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">4. <strong>Data Security</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- We implement a variety of security measures to protect your personal information. These include encryption, secure servers, and access controls to prevent unauthorized access, disclosure, or alteration of your data.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">5. <strong>Data Retention</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- We retain your personal information for as long as necessary to fulfil the purposes for which it was collected and to comply with legal obligations.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">6. <strong>Your Rights</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">6.1 Access and Correction:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- You have the right to access and correct your personal information. To do so, please contact us at contact@dinzin.in.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">6.2 Data Deletion:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- You may request the deletion of your personal information. However, certain information may be retained for legal or administrative purposes.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\"><strong>7. Cookies and Tracking Technologies</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- Our website uses cookies and similar tracking technologies to enhance your user experience. You can manage your cookie preferences through your browser settings.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">8. <strong>Changes to This Privacy Policy</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">- Dinzin Technology Solutions Pvt Ltd reserves the right to modify or update this Privacy Policy at any time. Changes will be effective immediately upon posting on our website. We encourage you to review this policy periodically.</span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>', '2024-08-04 17:43:48', '2024-08-04 22:16:05', 1);
INSERT INTO `modules` (`id`, `name`, `description`, `course_id`) VALUES
(1, 'INTRODUCTION', '<p>Welcome to the Dinzin Full Stack Web Developer Training Program, a comprehensive and immersive 3-month course designed to transform aspiring developers into skilled full stack professionals. This program is meticulously crafted to cover both front-end and back-end development, providing participants with a solid foundation in the latest web technologies and industry best practices.</p>\r\n<p>Our mission is to equip you with the practical skills and hands-on experience necessary to excel in the dynamic field of web development. Whether you are a beginner looking to start a new career or an experienced developer aiming to enhance your skill set, our program is tailored to meet your needs.</p>', 1),
(2, 'FRONTEND DEVELOPMENT BASICS', '<p>.</p>', 1),
(3, 'FRONTEND FRAMEWORKS', '<p>.</p>', 1),
(4, 'BACKEND DEVELOPMENT FUNDAMENTALS', '<p>.</p>', 1),
(5, 'Server-side Programming', '<p>.</p>', 1);
INSERT INTO `portfolio` (`id`, `name`, `description`, `screenshot`, `url`, `created_at`) VALUES
(7, 'Skylead Aviation', 'Designed a responsive website for an aviation company, highlighting services like pilot training and aircraft rentals. The site features a sleek design, user-friendly layout, and optimized content for online visibility.', 'uploads/674f1a44bedd6.png', 'https://www.skyleadaviation.com/', '2024-12-03 14:48:36'),
(8, 'Sky Bound Studios', 'Developed a custom website using HTML, CSS, JavaScript, and PHP for a creative studio, featuring a responsive design, dynamic content management, and an intuitive user experience.', 'uploads/674f1addaa46a.png', 'https://www.skyboundstudio.in/', '2024-12-03 14:51:09'),
(9, 'WiZdom Institutions Network', 'Created a dynamic and engaging website for Wizx, showcasing their offerings with a responsive design and optimized user experience to ensure seamless navigation across devices.', 'uploads/674f1b9749720.png', 'https://www.wizx.org/', '2024-12-03 14:54:15');
