(2, 1, 'Setup CI/CD pipeline', 'connect git repo to hosting servers with ftp', 1, 'pending', '2025-02-04 04:41:12', NULL, '00000', NULL),
(3, 1, 'migrate existing code to repo', 'initial code setup from bolt, migrate to the repo', 1, 'pending', '2025-02-04 04:43:06', NULL, '00000', NULL),
(4, 1, 'Test templates page', '- test if template page works correctly\r\n- test adding template works fine', 1, 'completed', '2025-02-04 05:24:21', NULL, '00000', NULL),
(5, 3, 'Project setup', 'Set a repo with all the dependencies', 1, 'completed', '2025-03-04 04:41:52', NULL, '00000', NULL),
(6, 3, 'Setup CI/CD pipeline - self hosted', 'connect git repo to hosting servers with ftp using github actions', 1, 'completed', '2025-03-04 04:45:15', NULL, '00000', NULL),
