(8, 3, 'Configure the hosting with the initial code', '- configure .htaccess and the initial code', 1, 'completed', '2025-03-04 04:58:57', NULL, '00000', NULL),
(9, 3, 'Search/submit functionality', '&lt;p&gt;Search / Submit Functionality&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;User should be able to select From location&lt;/li&gt;\r\n&lt;li&gt;User should be able to select Destination&lt;/li&gt;\r\n&lt;li&gt;User should be able to select No. of Passengers&lt;/li&gt;\r\n&lt;li&gt;User should be able to select Date&lt;/li&gt;\r\n&lt;li&gt;From and Destionation should be a dropdown of apirports&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;on submit&amp;nbsp;&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;store to backend&lt;/li&gt;\r\n&lt;li&gt;send data on whatsapp&lt;/li&gt;\r\n&lt;/ul&gt;', 1, 'completed', '2025-03-16 14:51:56', NULL, '00000', NULL),
(12, 3, 'Search Flights', '<ul>\r\n<li>register with Amadeus for API integration</li>\r\n<li>implemented fligth search api</li>\r\n<li>integrate search functionality in the booking section in homepage</li>\r\n</ul>', 1, 'completed', '2025-03-29 11:08:26', NULL, '00000', NULL),
(13, 1, 'User Authentication', '<p>Authentication using email &amp; phone number</p>\r\n<ul>\r\n<li>Register page\r\n<ul>\r\n<li>should be able to register using email and phone number\r\n<ul>\r\n<li>register page - email, phone, businessname/ indivial name, (if business - role), password</li>\r\n<li>verify email</li>\r\n<li>on verification - login and take use to dashboard</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>Login\r\n<ul>\r\n<li>should be able to login using email/phone &amp; password</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<p>&nbsp;</p>', 1, 'in-progress', '2025-04-04 09:11:04', NULL, '00000', NULL),
(14, 1, 'WhatsApp - Dashboard - Client onboard', '<p>From dashboard - users should be able to complete client onboard process using sign in with Facebook</p>\r\n<ul>\r\n<li>Show Start onboarding process button in the dashboard</li>\r\n<li>Users should be able to onboard / connect their whatsapp business account using sign in with facebook button / onboarding process button</li>\r\n<li>Should show the status of the onboard process</li>\r\n<li>On completion of onboarding - users should be able to see whatsapp marketing menus</li>\r\n</ul>', 1, 'pending', '2025-04-04 09:32:43', NULL, '00000', NULL),
(27, 1, 'Asset urls', '<ul>\r\n<li>Identify the resource urls in the templates</li>\r\n<li>&nbsp;replace resource urls like src<span style=\"background-color: #000c18; color: #6688cc; font-family: Consolas, \'Courier New\', monospace; font-size: 14px; white-space: pre;\">=</span><span style=\"font-family: Consolas, \'Courier New\', monospace; font-size: 14px; white-space: pre; color: #22aa44;\">\"./images/logo/logo-dark.svg\" with src=\"{{assets(\'theme/images/logo/logo-dark.svg\')}}\"- example urls<br /></span><br /><br /><br /></li>\r\n</ul>', 4, 'completed', '2025-07-02 17:40:50', '4', '53576', '[]'),
(28, 1, 'Chat interface in whatsapp tool', '<ul>\r\n<li>Reference: <a href=\"https://demo.tailadmin.com/chat\">https://demo.tailadmin.com/chat</a></li>\r\n<li>Replicate this chat interface in the route \'/chat\' in whatsapp-tool repo</li>\r\n</ul>', 5, 'in-progress', '2025-07-02 17:59:37', '1', '84819', '[]'),
(29, 1, 'Sidebar menus', '<p>Remove theme default menus and add these menus</p>\r\n<ol>\r\n<li>Dashboard</li>\r\n<li>Templates</li>\r\n<li>Campaigns</li>\r\n<li>Chat</li>\r\n</ol>', 4, 'completed', '2025-07-04 17:20:52', '1', '88884', '[]'),
(30, 1, 'Template menu interface', '<p>Template menu</p>\r\n<ul>\r\n<li>create template button</li>\r\n<li>list of templates with their status\r\n<ul>\r\n<li>name, category approved, status</li>\r\n</ul>\r\n</li>\r\n<li>pagination</li>\r\n</ul>\r\n<p>Refer templates menu in whatsapp business manager</p>', 4, 'pending', '2025-07-06 14:36:04', '1', '30782', '[]');
